import{_ as l,C as o,o as a,c as i,a2 as r,b as s,w as E,a as B,E as n,a3 as A}from"./chunks/framework.BBdhqAg0.js";const C="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",D=JSON.parse('{"title":"운영비 내역 관리","description":"","frontmatter":{},"headers":[],"relativePath":"ledger/imprest.md","filePath":"ledger/imprest.md","lastUpdated":1793195756000}'),d={name:"ledger/imprest.md"};function g(c,t,h,_,m,p){const e=o("Mermaid");return a(),i("div",null,[t[1]||(t[1]=r('<h1 id="운영비-내역-관리" tabindex="-1">운영비 내역 관리 <a class="header-anchor" href="#운영비-내역-관리" aria-label="Permalink to &quot;운영비 내역 관리&quot;">​</a></h1><p>프로젝트 수행을 위해 별도로 운영되는 운영비(전도금) 계좌의 입출금 내역을 기록하고, 이를 회계 계정 및 프로젝트별 계약 정보와 연결하여 관리하는 화면입니다.</p><ul><li><strong>위치</strong>: <code>회계 자금 관리 &gt; 운영비 내역 관리</code></li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+C+'" alt="운영비 내역 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/imprest.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>대규모 공사비나 토지대금을 집행하는 본 사업비 계좌(신탁/PF 계좌) 외에, 프로젝트 사업단이나 현장 사무소의 일상 경비(여비교통비, 소모품비, 현장 식대, 일상 용역비 등) 집행을 위해 운용하는 운영비 계좌(전도금 계좌)의 거래를 관리합니다. 등록된 거래는 회계 계정과목 및 적격 지출 증빙과 정확히 매칭되며, 본사 자금일보와 실시간 연동되어 운영비 집행의 투명성을 확보합니다.</p>',6)),(a(),s(A,null,{default:E(()=>[n(e,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EC%9A%B4%EC%98%81%20%EA%B3%84%EC%A2%8C%20%EC%84%A0%ED%83%9D%3Cbr%2F%3E(%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EC%A0%84%EB%8F%84%EA%B8%88%20%ED%86%B5%EC%9E%A5)%22%5D%20--%3E%20B%5B%222.%20%EC%9A%B4%EC%98%81%EB%B9%84%20%EC%9E%85%EC%B6%9C%EA%B8%88%20%EB%93%B1%EB%A1%9D%3Cbr%2F%3E(%EC%A0%84%EB%8F%84%EA%B8%88%20%EC%9E%85%EA%B8%88%C2%B7%EC%9D%BC%EC%83%81%EA%B2%BD%EB%B9%84%20%EC%A7%80%EC%B6%9C)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%ED%9A%8C%EA%B3%84%20%EA%B3%84%EC%A0%95%20%EB%B0%8F%20%EC%A6%9D%EB%B9%99%20%EB%B6%84%EB%A5%98%3Cbr%2F%3E(%EC%97%AC%EB%B9%84%EA%B5%90%ED%86%B5%EB%B9%84%C2%B7%EC%8B%9D%EB%8C%80%C2%B7%EC%86%8C%EB%AA%A8%ED%92%88%EB%B9%84%20%EB%93%B1)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%9D%B8%EB%9D%BC%EC%9D%B8%20%EB%B9%A0%EB%A5%B8%20%ED%8E%B8%EC%A7%91%20%EB%B0%8F%20%EB%8C%80%EC%82%AC%3Cbr%2F%3E(%EB%8D%94%EB%B8%94%ED%81%B4%EB%A6%AD%20%EC%88%98%EC%A0%95%C2%B7%EC%B0%A8%EC%95%A1%20%EA%B2%80%EC%A6%9D%20%E2%9C%85)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%EB%B3%B8%EC%82%AC%20%EC%9E%90%EA%B8%88%EC%9D%BC%EB%B3%B4%20%EC%97%B0%EB%8F%99%3Cbr%2F%3E(%EC%9A%B4%EC%98%81%EB%B9%84%20%EC%A0%95%EC%82%B0%20%EB%B0%8F%20%EC%A6%9D%EB%B9%99%20%EB%A7%88%EA%B0%90)%22%5D%0A"})]),fallback:E(()=>[...t[0]||(t[0]=[B(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>운영비(전도금) 전용 특화 조회</strong>: 프로젝트별로 개설된 운영 계좌를 기준으로 기간별, 비목별 지출 명세 집중 관리</li><li><strong>다수 거래 일괄 입력 지원</strong>: 영수증 정산 시 여러 건의 일상 경비 지출 내역을 한 화면에서 행 단위로 빠르게 등록</li><li><strong>인라인 다이렉트 편집 (Inline Editing)</strong>: 목록 화면에서 항목을 더블 클릭하여 적요, 메모, 금액, 계정과목 등을 이동 없이 즉시 수정</li><li><strong>이체 수수료 자동 분개</strong>: 인터넷 뱅킹 이체 시 발생하는 송금 수수료(500원) 분개를 원클릭으로 자동 생성</li><li><strong>대체 거래(자금 이동) 자동 처리</strong>: 본사 계좌에서 운영비 통장으로 전도금을 입금받거나 계좌 간 자금 이동 시 상대측 전표 자동 생성 제안</li><li><strong>엑셀 템플릿 연동</strong>: 대량의 월간 운영비 정산 내역을 엑셀 서식으로 다운로드 및 대량 업로드 지원</li><li><strong>화면 간 하이라이트 포커싱</strong>: 자금 일보 등 외부 화면에서 특정 운영비 링크를 타고 진입 시 해당 거래 행을 자동으로 찾아 스크롤 및 강조 표시</li></ul><h2 id="화면-구성-및-실무-가이드" tabindex="-1">화면 구성 및 실무 가이드 <a class="header-anchor" href="#화면-구성-및-실무-가이드" aria-label="Permalink to &quot;화면 구성 및 실무 가이드&quot;">​</a></h2><h3 id="_1-목록-제어-및-검색-필터" tabindex="-1">1. 목록 제어 및 검색 필터 <a class="header-anchor" href="#_1-목록-제어-및-검색-필터" aria-label="Permalink to &quot;1. 목록 제어 및 검색 필터&quot;">​</a></h3><p>특정 프로젝트의 운영비 지출 내역을 조건별로 검색하고 규모를 파악하는 영역입니다.</p><ul><li><strong>검색 조건</strong>: 거래일자 범위, 입출금 구분(전체/입금/출금), 계정과목 분류, 운영 계좌 선택, 관련 계약 정보 및 검색어(적요/거래처)</li><li><strong>실시간 데이터 집계</strong>: 조회 조건에 부합하는 총 거래 건수와 지출 합계가 즉시 표시되어 월별 경비 규모를 한눈에 파악할 수 있습니다.</li></ul><h3 id="_2-운영비-입출금-현황-목록" tabindex="-1">2. 운영비 입출금 현황 목록 <a class="header-anchor" href="#_2-운영비-입출금-현황-목록" aria-label="Permalink to &quot;2. 운영비 입출금 현황 목록&quot;">​</a></h3><p>조회된 내역을 직관적인 테이블 형태로 표시하며, 상단의 통장 원장과 하단의 회계 분개로 구성됩니다.</p><ul><li><strong>은행거래내역 (통장 원장)</strong>: 실제 통장에 기록된 거래일자, 계좌 별칭, 통장 적요, 입금액/출금액 정보</li><li><strong>분류 내역 (회계 분개)</strong>: 해당 거래의 회계 계정과목, 거래처, 분류 금액, 지출 증빙 유형(신용카드, 세금계산서, 현금영수증 등)</li><li><strong>금액 일치 검증</strong>: 통장 입출금액과 하단 분류 내역 금액의 합계가 일치하면 **초록색 체크(✅)**가 표시되며, 차액 발생 시 노란색 경고 행으로 부족하거나 초과된 금액을 안내합니다.</li></ul><h3 id="_3-거래-등록-및-수정-폼" tabindex="-1">3. 거래 등록 및 수정 폼 <a class="header-anchor" href="#_3-거래-등록-및-수정-폼" aria-label="Permalink to &quot;3. 거래 등록 및 수정 폼&quot;">​</a></h3><p>새로운 운영비 거래를 등록하거나 기존 지출 건을 수정하는 화면입니다.</p><ul><li><strong>신규 거래 등록 (다수 건)</strong>: [새 거래 등록] 버튼을 눌러 여러 건의 영수증 지출 내역을 연속해서 입력할 수 있습니다.</li><li><strong>인라인 즉시 수정</strong>: 목록에서 수정하고자 하는 셀(적요, 메모 등)을 마우스로 <strong>더블 클릭</strong>하면 팝업 없이 즉시 텍스트를 수정할 수 있습니다.</li><li><strong>상세 수정 모달</strong>: 복잡한 계정 분할이나 지출 증빙 파일 첨부가 필요한 경우 개별 행의 수정 아이콘을 클릭하여 상세 편집창을 호출합니다.</li></ul><h2 id="💡-실무-활용-팁-및-관리-포인트" tabindex="-1">💡 실무 활용 팁 및 관리 포인트 <a class="header-anchor" href="#💡-실무-활용-팁-및-관리-포인트" aria-label="Permalink to &quot;💡 실무 활용 팁 및 관리 포인트&quot;">​</a></h2><ul><li><strong>인라인 편집 시 계정 연동 팝업 주의</strong>: 목록에서 계정과목 셀을 더블 클릭하여 수정할 때, 선택한 계정이 분양 계약이나 외주 용역 계약 매칭이 필수인 계정인 경우 시스템이 자동으로 계약 선택 모달을 띄워 데이터 누락을 방지합니다.</li><li><strong>대체 거래(전도금 수령) 처리 요령</strong>: 본사에서 현장 운영비 계좌로 500만 원의 전도금을 송금한 경우, 본사 출금 거래 등록 시 계정과목을 &#39;대체(출금)&#39;으로 지정하면 현장 운영비 계좌의 &#39;대체(입금)&#39; 거래를 자동으로 생성할 것인지 묻는 확인 창이 뜹니다. 이를 승인하면 양측 계좌의 자금 흐름이 자동으로 일치됩니다.</li><li><strong>소액 지출 증빙 관리</strong>: 운영비는 식대, 소모품 등 소액 카드 결제 및 간이영수증이 많습니다. [지출 증빙] 항목에서 적격 증빙(카드, 현금영수증, 세금계산서) 구분을 정확히 지정해 두어야 부가세 매입세액 공제 신고 시 누락을 방지할 수 있습니다.</li><li><strong>과거 데이터 수정 제한 (정산 마감 보호)</strong>: 최종 정산이 완료된 일자 이전의 데이터나 등록 후 10일이 경과한 거래는 임의 수정이 제한됩니다. 수정이 꼭 필요한 사유가 발생한 경우 상급 관리자에게 정산 잠금 해제를 요청해야 합니다.</li></ul>',14))])}const b=l(d,[["render",g]]);export{D as __pageData,b as default};
